import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

interface Solicitacao {
  id: number;
  nome_solicitante: string;
  setor: string;
  titulo: string;
  local: string;
  descricao: string;
  status: string;
  prioridade: string | null;
  data_criacao: string;
}

interface Tecnico {
  id: number;
  nome: string;
  telefone: string;
  email: string;
  token: string;
  ativo: boolean;
}

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [solicitacoes, setSolicitacoes] = useState<Solicitacao[]>([]);
  const [tecnicos, setTecnicos] = useState<Tecnico[]>([]);
  const [novoTecnico, setNovoTecnico] = useState({
    nome: '',
    telefone: '',
    email: ''
  });
  const [mensagem, setMensagem] = useState<{ tipo: 'sucesso' | 'erro'; texto: string } | null>(null);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/admin/login');
      return;
    }

    carregarDados();
  }, [navigate]);

  const carregarDados = async () => {
    try {
      const token = localStorage.getItem('token');
      const config = { headers: { Authorization: `Bearer ${token}` } };

      const [solicitacoesRes, tecnicosRes] = await Promise.all([
        axios.get('http://localhost:3001/api/solicitacoes', config),
        axios.get('http://localhost:3001/api/admin/tecnicos', config)
      ]);

      setSolicitacoes(solicitacoesRes.data);
      setTecnicos(tecnicosRes.data);
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
    }
  };

  const handleAprovarSolicitacao = async (id: number, prioridade: string) => {
    try {
      const token = localStorage.getItem('token');
      await axios.patch(
        `http://localhost:3001/api/admin/solicitacoes/${id}`,
        { status: 'aprovada', prioridade },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      setMensagem({ tipo: 'sucesso', texto: 'Solicitação aprovada com sucesso!' });
      carregarDados();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao aprovar solicitação' });
    }
  };

  const handleReprovarSolicitacao = async (id: number) => {
    try {
      const token = localStorage.getItem('token');
      await axios.patch(
        `http://localhost:3001/api/admin/solicitacoes/${id}`,
        { status: 'reprovada' },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      setMensagem({ tipo: 'sucesso', texto: 'Solicitação reprovada' });
      carregarDados();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao reprovar solicitação' });
    }
  };

  const handleCadastrarTecnico = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:3001/api/admin/tecnicos',
        novoTecnico,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setMensagem({
        tipo: 'sucesso',
        texto: `Técnico cadastrado com sucesso! Link de acesso: ${response.data.tecnico.link_acesso}`
      });
      setNovoTecnico({ nome: '', telefone: '', email: '' });
      carregarDados();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao cadastrar técnico' });
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('adminData');
    navigate('/admin/login');
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <nav className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <h1 className="text-xl font-semibold text-gray-900">Painel do Administrador</h1>
            </div>
            <div className="flex items-center">
              <button
                onClick={handleLogout}
                className="ml-4 px-4 py-2 text-sm text-red-600 hover:text-red-900"
              >
                Sair
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        {mensagem && (
          <div className={`mb-4 rounded-md p-4 ${
            mensagem.tipo === 'sucesso' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
          }`}>
            <p className="text-sm">{mensagem.texto}</p>
          </div>
        )}

        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          {/* Lista de Solicitações */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-gray-900 mb-4">Solicitações Pendentes</h2>
            <div className="space-y-4">
              {solicitacoes
                .filter(s => s.status === 'pendente')
                .map(solicitacao => (
                  <div key={solicitacao.id} className="border rounded-lg p-4">
                    <h3 className="font-medium">{solicitacao.titulo}</h3>
                    <p className="text-sm text-gray-500">
                      Solicitante: {solicitacao.nome_solicitante} - Setor: {solicitacao.setor}
                    </p>
                    <p className="text-sm text-gray-500">Local: {solicitacao.local}</p>
                    {solicitacao.descricao && (
                      <p className="text-sm text-gray-500 mt-2">{solicitacao.descricao}</p>
                    )}
                    <div className="mt-4 flex items-center space-x-4">
                      <select
                        className="text-sm border rounded p-1"
                        onChange={(e) => handleAprovarSolicitacao(solicitacao.id, e.target.value)}
                        defaultValue=""
                      >
                        <option value="" disabled>Selecione a prioridade</option>
                        <option value="alta">Alta</option>
                        <option value="media">Média</option>
                        <option value="baixa">Baixa</option>
                      </select>
                      <button
                        onClick={() => handleReprovarSolicitacao(solicitacao.id)}
                        className="text-sm text-red-600 hover:text-red-900"
                      >
                        Reprovar
                      </button>
                    </div>
                  </div>
                ))}
            </div>
          </div>

          {/* Cadastro de Técnicos */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-gray-900 mb-4">Cadastrar Novo Técnico</h2>
            <form onSubmit={handleCadastrarTecnico} className="space-y-4">
              <div>
                <label htmlFor="nome" className="block text-sm font-medium text-gray-700">
                  Nome
                </label>
                <input
                  type="text"
                  id="nome"
                  name="nome"
                  required
                  value={novoTecnico.nome}
                  onChange={(e) => setNovoTecnico(prev => ({ ...prev, nome: e.target.value }))}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
                />
              </div>
              <div>
                <label htmlFor="telefone" className="block text-sm font-medium text-gray-700">
                  Telefone
                </label>
                <input
                  type="tel"
                  id="telefone"
                  name="telefone"
                  required
                  value={novoTecnico.telefone}
                  onChange={(e) => setNovoTecnico(prev => ({ ...prev, telefone: e.target.value }))}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
                />
              </div>
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-gray-700">
                  Email
                </label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  required
                  value={novoTecnico.email}
                  onChange={(e) => setNovoTecnico(prev => ({ ...prev, email: e.target.value }))}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
                />
              </div>
              <button
                type="submit"
                className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500"
              >
                Cadastrar Técnico
              </button>
            </form>

            <div className="mt-8">
              <h3 className="text-lg font-medium text-gray-900 mb-4">Técnicos Cadastrados</h3>
              <div className="space-y-4">
                {tecnicos.map(tecnico => (
                  <div key={tecnico.id} className="border rounded-lg p-4">
                    <h4 className="font-medium">{tecnico.nome}</h4>
                    <p className="text-sm text-gray-500">Telefone: {tecnico.telefone}</p>
                    <p className="text-sm text-gray-500">Email: {tecnico.email}</p>
                    <p className="text-sm text-gray-500 mt-2">
                      Link de acesso: /tecnico/acesso/{tecnico.token}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
